input.command:
node <<'EOF'
const fs = require('fs');
const path = require('path');
const files = [];
for (const dir of ['src', 'test']) {
  for (const f of fs.readdirSync(dir)) {
    const p = path.join(dir, f);
    if (fs.statSync(p).isFile() && p.endsWith('.js')) files.push(p);
  }
}
let renamed = 0, bumped = 0;
for (const p of files) {
  const orig = fs.readFileSync(p, 'utf8');
  let s = orig.replace(/\bretryPolicy\b/g, () => { renamed++; return 'backoffPolicy'; });
  s = s.replace(/\bmaxAttempts: 3\b/g, () => { bumped++; return 'maxAttempts: 5'; });
  if (s !== orig) fs.writeFileSync(p, s);
}
console.log(`files scanned: ${files.length}, identifiers renamed: ${renamed}, maxAttempts bumped: ${bumped}`);
EOF
echo "--- leftover checks ---"
grep -rn "retryPolicy\|maxAttempts: 3\b" src test || echo "none"
echo "--- node --test ---"
node --test 2>&1; echo "exit code: $?"

